// shared.module.ts
@NgModule({
  declarations: [HighlightDirective, TruncatePipe],
  imports: [CommonModule, FormsModule],
  exports: [CommonModule, FormsModule, HighlightDirective, TruncatePipe]
})
export class SharedModule {}

// core.module.ts
@NgModule({
  imports: [SharedModule],  // optional, if core components use shared
  exports: [],
  providers: [AuthService, LoggerService]
})
export class CoreModule {
  constructor(@Optional() @SkipSelf() parentModule: CoreModule) {
    if (parentModule) {
      throw new Error('CoreModule is already loaded.');
    }
  }
}

// app.module.ts
@NgModule({
  imports: [
    BrowserModule,
    CoreModule,
    // feature modules that import SharedModule
  ],
  ...
})
export class AppModule {}
